arguments.command:
export DRIVE_TARGET=linux; export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; D=.claude/skills/agent-emulator-debugging/scripts/drive.py;
for i in {1..15}; do 
  STATE=$($D call ext.nothingness.getPlaybackState); 
  echo "iter $i"; 
  echo "$STATE" | python3 - <<'PY'
import sys,json
s=json.load(sys.stdin)
info=s.get('songInfo') or {}
print('isPlaying',s.get('isPlaying'),'pos',info.get('position'),'dur',info.get('duration'))
PY
  dur=$(echo "$STATE"|python3 -c 'import sys,json; s=json.load(sys.stdin); print((s.get("songInfo") or {}).get("duration") or 0)')
  pos=$(echo "$STATE"|python3 -c 'import sys,json; s=json.load(sys.stdin); print((s.get("songInfo") or {}).get("position") or 0)')
  if [ "$dur" != "null" ] && [ "$dur" -gt 0 ] && [ "$pos" -ge 0 ]; then 
    if [ "$dur" -gt 0 ]; then echo ready; break; fi;
  fi;
  sleep 1;
done

